import socket,struct
def q(name, server='127.0.0.11'):
    tid=b'\xab\xcd'; flags=b'\x01\x00'; qd=b'\x00\x01'; rest=b'\x00\x00\x00\x00\x00\x00'
    qn=b''.join(bytes([len(p)])+p.encode() for p in name.split('.'))+b'\x00'
    pkt=tid+flags+qd+rest+qn+b'\x00\x01\x00\x01'
    s=socket.socket(socket.AF_INET,socket.SOCK_DGRAM); s.settimeout(3)
    s.sendto(pkt,(server,53))
    d,_=s.recvfrom(4096)
    print(name, len(d), d[-8:].hex())
    ips=[]
    # crude parse: look for answer A records
    i=12
    def skipname(d,i):
        while d[i]:
            if d[i]&0xC0: return i+2
            i+=d[i]+1
        return i+1
    i=skipname(d,i); i+=4
    for _ in range(3):
        i=skipname(d,i)
        typ=struct.unpack('>H',d[i:i+2])[0]; i+=8
        ln=struct.unpack('>H',d[i:i+2])[0]; i+=2
        if typ==1: ips.append(socket.inet_ntoa(d[i:i+ln]))
        i+=ln
    return ips
for n in ['prices.internal','commons.local','prices.internal.any']:
    try: print(n, q(n))
    except Exception as e: print(n,'ERR',e)
EOF"}

